target.css:
:root {
  --ink: #183044;
  --paper: #fffdf6;
  --line: #b9d5d1;
  --aqua: #bce8e0;
  --deep-aqua: #287f87;
}

.marble-card {
  width: 460px;
  box-sizing: border-box;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--line);
  border-radius: 14px;
}

.card-header,
.card-footer,
.sample-row {
  display: flex;
  align-items: center;
}

.card-header {
  justify-content: space-between;
}

.eyebrow {
  color: var(--deep-aqua);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1px;
}

.status {
  padding: 4px 8px;
  color: var(--deep-aqua);
  background: var(--aqua);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
}

.sample-row {
  gap: 12px;
  margin: 14px 0;
}

.swatch {
  width: 46px;
  height: 46px;
  flex: 0 0 auto;
  background: var(--aqua);
  border: 2px solid var(--deep-aqua);
  border-radius: 12px 4px 12px 4px;
}

.sample-copy h1 {
  margin: 0 0 3px;
  font-size: 20px;
  line-height: 1.1;
}

.sample-copy p {
  margin: 0;
  color: var(--deep-aqua);
  font-size: 13px;
}

.card-footer {
  justify-content: space-between;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  color: var(--deep-aqua);
  font-size: 12px;
  font-weight: 700;
}

button {
  padding: 6px 10px;
  color: var(--paper);
  background: var(--deep-aqua);
  border: 0;
  border-radius: 7px;
  font-weight: 800;
}
